1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body { margin: 0; padding: 2rem 1rem; font: 16px/1.4 system-ui, sans-serif; background: #f6f6f4; color: #222; }
10	  main { max-width: 32rem; margin: 0 auto; }
11	  h1 { margin: 0 0 1rem; font-size: 1.5rem; }
12	  form { display: flex; gap: .5rem; margin-bottom: 1rem; }
13	  input { flex: 1; padding: .5rem .75rem; font: inherit; border: 1px solid #ccc; border-radius: 6px; }
14	  button { padding: .5rem .9rem; font: inherit; border: 1px solid #bbb; border-radius: 6px; background: #fff; cursor: pointer; }
15	  button:hover { background: #eee; }
16	  ul { list-style: none; margin: 0; padding: 0; }
17	  li { display: flex; align-items: center; gap: .5rem; padding: .5rem .75rem; margin-bottom: .4rem; background: #fff; border: 1px solid #e2e2e2; border-radius: 6px; }
18	  li span { flex: 1; overflow-wrap: anywhere; }
19	  li[data-completed="true"] span { text-decoration: line-through; color: #888; }
20	  li input[type="checkbox"] { flex: none; width: 1.1rem; height: 1.1rem; margin: 0; }
21	  .filters { display: flex; gap: .5rem; margin-bottom: 1rem; }
22	  .filters button[aria-pressed="true"] { background: #222; border-color: #222; color: #fff; }
23	  form input[type="date"] { flex: none; }
24	  .due { flex: none; font-size: .85rem; color: #666; }
25	  li[data-overdue="true"] { border-color: #d33; background: #fff1f0; }
26	  li[data-overdue="true"] .due { color: #b00; font-weight: 600; }
27	  form select { flex: none; padding: .5rem; font: inherit; border: 1px solid #ccc; border-radius: 6px; background: #fff; }
28	  li[data-priority] { border-left-width: 5px; }
29	  li[data-priority="high"] { border-left-color: #d33; }
30	  li[data-priority="med"] { border-left-color: #e0a100; }
31	  li[data-priority="low"] { border-left-color: #999; }
32	  .priority { flex: none; font-size: .75rem; font-weight: 600; text-transform: uppercase; padding: .1rem .4rem; border-radius: 4px; }
33	  li[data-priority="high"] .priority { background: #fde2e1; color: #b00; }
34	  li[data-priority="med"] .priority { background: #fdf0cc; color: #8a5a00; }
35	  li[data-priority="low"] .priority { background: #ececec; color: #555; }
36	</style>
37	</head>
38	<body>
39	<main>
40	  <h1>Todos</h1>
41	  <form id="todo-form">
42	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
43	    <input data-testid="todo-due" type="date" aria-label="Due date (optional)">
44	    <select data-testid="todo-priority" aria-label="Priority">
45	      <option value="low">Low</option>
46	      <option value="med" selected>Med</option>
47	      <option value="high">High</option>
48	    </select>
49	    <button data-testid="todo-add" type="submit">Add</button>
50	  </form>
51	  <div class="filters" role="group" aria-label="Filter todos">
52	    <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
53	    <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
54	    <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
55	  </div>
56	  <ul data-testid="todo-list"></ul>
57	</main>
58	<script>
59	  var STORAGE_KEY = 'todos';
60	  var form = document.getElementById('todo-form');
61	  var input = document.querySelector('[data-testid="todo-input"]');
62	  var dueInput = document.querySelector('[data-testid="todo-due"]');
63	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
64	  var list = document.querySelector('[data-testid="todo-list"]');
65	  var filterButtons = document.querySelectorAll('[data-filter]');
66	  var currentFilter = 'all';
67	
68	  // [REQ-001] Load todos from localStorage; ignore malformed data.
69	  function loadTodos() {
70	    try {
71	      var parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
72	      if (!Array.isArray(parsed)) return [];
73	      // [REQ-002] Todos saved before completion existed default to active.
74	      parsed.forEach(function (t) {
75	        t.completed = t.completed === true;
76	        // [REQ-003] Drop anything that is not a plain YYYY-MM-DD string.
77	        t.due = normalizeDue(t.due);
78	        // [REQ-004] Todos saved before priorities existed default to med.
79	        t.priority = normalizePriority(t.priority);
80	      });
81	      return parsed;
82	    } catch (e) {
83	      return [];
84	    }
85	  }
86	
87	  // [REQ-001]
88	  function saveTodos() {
89	    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(todos)); } catch (e) {}
90	  }
91	
92	  // [REQ-001] Stable unique id; crypto.randomUUID is not available in every file:// context.
93	  function makeId() {
94	    if (window.crypto && typeof crypto.randomUUID === 'function') {
95	      try { return crypto.randomUUID(); } catch (e) {}
96	    }
97	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
98	  }
99	
100	  // [REQ-003] Due dates are plain YYYY-MM-DD strings, treated as local calendar dates. Never parsed through UTC.
101	  function normalizeDue(value) {
102	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null;
103	  }
104	
105	  // [REQ-004] Priority is one of low, med, high; anything else becomes med.
106	  function normalizePriority(value) {
107	    return value === 'low' || value === 'high' ? value : 'med';
108	  }
109	
110	  // [REQ-003] Today's local calendar date as YYYY-MM-DD.
111	  function localToday(now) {
112	    function pad(n) { return (n < 10 ? '0' : '') + n; }
113	    return now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
114	  }
115	
116	  // [REQ-003] Overdue means strictly before today's local date. Same-format strings compare correctly as text.
117	  function isOverdue(due, today) {
118	    return due !== null && due < today;
119	  }
120	
121	  // [REQ-002] Ordering decision: active todos first, completed below; insertion order within each group.
122	  // The todos array is kept in insertion order, so a stable split preserves it.
123	  function orderTodos(items) {
124	    return items.filter(function (t) { return !t.completed; })
125	      .concat(items.filter(function (t) { return t.completed; }));
126	  }
127	
128	  // [REQ-002]
129	  function matchesFilter(todo, filter) {
130	    if (filter === 'active') return !todo.completed;
131	    if (filter === 'completed') return todo.completed;
132	    return true;
133	  }
134	
135	  // [REQ-001] [REQ-002] [REQ-003] [REQ-004]
136	  function render() {
137	    list.textContent = '';
138	    var today = localToday(new Date());
139	    filterButtons.forEach(function (btn) {
140	      btn.setAttribute('aria-pressed', String(btn.dataset.filter === currentFilter));
141	    });
142	    orderTodos(todos).filter(function (t) { return matchesFilter(t, currentFilter); }).forEach(function (todo) {
143	      var li = document.createElement('li');
144	      li.setAttribute('data-testid', 'todo-item');
145	      li.setAttribute('data-completed', String(todo.completed));
146	      li.setAttribute('data-overdue', String(isOverdue(todo.due, today)));
147	      li.setAttribute('data-priority', todo.priority);
148	      li.dataset.id = todo.id;
149	
150	      var toggle = document.createElement('input');
151	      toggle.type = 'checkbox';
152	      toggle.setAttribute('data-testid', 'todo-toggle');
153	      toggle.checked = todo.completed;
154	      toggle.setAttribute('aria-label', 'Mark "' + todo.text + '" ' + (todo.completed ? 'incomplete' : 'complete'));
155	      toggle.addEventListener('change', function () { toggleTodo(todo.id); });
156	
157	      var text = document.createElement('span');
158	      text.setAttribute('data-testid', 'todo-text');
159	      text.textContent = todo.text;
160	
161	      var del = document.createElement('button');
162	      del.type = 'button';
163	      del.setAttribute('data-testid', 'todo-delete');
164	      del.textContent = 'Delete';
165	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
166	      del.addEventListener('click', function () { deleteTodo(todo.id); });
167	
168	      li.appendChild(toggle);
169	      li.appendChild(text);
170	      var priority = document.createElement('span');
171	      priority.className = 'priority';
172	      priority.textContent = todo.priority;
173	      li.appendChild(priority);
174	      if (todo.due) {
175	        var due = document.createElement('span');
176	        due.className = 'due';
177	        due.setAttribute('data-testid', 'todo-due-date');
178	        due.textContent = 'Due ' + todo.due;
179	        li.appendChild(due);
180	      }
181	      li.appendChild(del);
182	      list.appendChild(li);
183	    });
184	  }
185	
186	  // [REQ-001] [REQ-003] [REQ-004]
187	  function addTodo(rawText, rawDue, rawPriority) {
188	    var text = rawText.trim();
189	    if (!text) return;
190	    todos.push({ id: makeId(), text: text, createdAt: Date.now(), completed: false, due: normalizeDue(rawDue), priority: normalizePriority(rawPriority) });
191	    saveTodos();
192	    render();
193	  }
194	
195	  // [REQ-001]
196	  function deleteTodo(id) {
197	    todos = todos.filter(function (t) { return t.id !== id; });
198	    saveTodos();
199	    render();
200	  }
201	
202	  // [REQ-002] Flip completion in place; the array keeps insertion order.
203	  function toggleTodo(id) {
204	    todos.forEach(function (t) { if (t.id === id) t.completed = !t.completed; });
205	    saveTodos();
206	    render();
207	  }
208	
209	  var todos = loadTodos();
210	
211	  filterButtons.forEach(function (btn) {
212	    btn.addEventListener('click', function () {
213	      currentFilter = btn.dataset.filter;
214	      render();
215	    });
216	  });
217	
218	  form.addEventListener('submit', function (e) {
219	    e.preventDefault();
220	    addTodo(input.value, dueInput.value, priorityInput.value);
221	    input.value = '';
222	    dueInput.value = '';
223	    priorityInput.value = 'med';
224	    input.focus();
225	  });
226	
227	  // [REQ-003] Recompute overdue state when the page regains focus, in case the local date has changed.
228	  window.addEventListener('focus', render);
229	
230	  render();
231	</script>
232	</body>
233	</html>
