// [REQ-002] [REQ-005] Ordering: active todos first, completed below (DEC-003).
// Within each group: high, then med, then low; insertion order within the same priority.
// The todos array is kept in insertion order; bucketing by priority is stable, so it preserves that order.
function orderTodos(items) {
  function byPriority(group) {
    return ['high', 'med', 'low'].reduce(function (out, p) {
      return out.concat(group.filter(function (t) { return t.priority === p; }));
    }, []);
  }
  return byPriority(items.filter(function (t) { return !t.completed; }))
    .concat(byPriority(items.filter(function (t) { return t.completed; })));
}

